"""Generate the fictional fixture data used by the tests and by `--demo`.

Every company, ticker, price and headline here is invented. Run from the repo root:
    python tests/fixtures/make_fixtures.py
"""

from __future__ import annotations

import json
import math
import random
import re
from datetime import date, datetime, timedelta, timezone
from pathlib import Path

import yaml

HERE = Path(__file__).resolve().parent
DEMO_DAY = date(2026, 11, 19)
random.seed(19)

TICKERS = {
    "benchmarks": {"DMKT": "Demo Market Index", "DFIN": "Demo Fintech ETF"},
    "groups": {
        "Office of the CFO software": {"LDGR": "Ledgerline", "CLSE": "Closewise", "SPND": "Spendly", "PAYR": "Payroller"},
        "Payments & lending": {"ORBT": "Orbit Pay", "LUMN": "Lumen Lending", "TAPP": "Tapp"},
        "Recent fintech IPOs": {"VLTA": "Vaulta", "NOVA": "Nova Bank", "GHST": "Ghost Ticker Co"},
    },
}
DRIFT = {"DMKT": 0.0006, "DFIN": 0.0009, "LDGR": 0.0025, "CLSE": 0.0018, "SPND": -0.0012, "PAYR": 0.0004,
         "ORBT": -0.0020, "LUMN": 0.0010, "TAPP": 0.0030, "VLTA": 0.0045, "NOVA": -0.0030}
START_PRICE = {"DMKT": 512, "DFIN": 31, "LDGR": 88, "CLSE": 142, "SPND": 47, "PAYR": 230,
               "ORBT": 64, "LUMN": 19, "TAPP": 12, "VLTA": 41, "NOVA": 26}
FEEDS = {
    "CFO Wire": "https://feeds.example.com/cfo-wire/rss",
    "Payments Weekly": "https://feeds.example.com/payments-weekly/atom",
    "News search: fintech": "https://news.example.com/rss/search?q=fintech",
    "Broken Feed": "https://feeds.example.com/this-feed-is-down",
}


def series(ticker: str, n: int = 252) -> list[float]:
    p, out = START_PRICE[ticker], []
    for i in range(n):
        shock = random.gauss(0, 0.018)
        if ticker == "TAPP" and i > n - 6:
            shock += 0.03  # a sharp recent run-up so the demo has a clear mover
        if ticker == "ORBT" and i > n - 6:
            shock -= 0.025
        p *= math.exp(DRIFT[ticker] + shock)
        out.append(round(p, 2))
    return out


def yahoo(ticker: str) -> dict:
    closes = series(ticker)
    end = datetime(2026, 11, 18, 21, tzinfo=timezone.utc)
    stamps = [int((end - timedelta(days=(len(closes) - i) * 1.45)).timestamp()) for i in range(len(closes))]
    closes[100] = None  # Yahoo sometimes returns gaps; the parser must skip them
    return {"chart": {"result": [{"meta": {"symbol": ticker, "currency": "USD", "regularMarketPrice": closes[-1]},
                                  "timestamp": stamps,
                                  "indicators": {"quote": [{"close": closes}], "adjclose": [{"adjclose": closes}]}}],
                      "error": None}}


def hit(name, ticker, cik, form, filed, sic, state):
    adsh = f"{random.randint(1000000000, 1999999999):010d}-26-{random.randint(100000, 999999)}"
    disp = f"{name}  ({ticker})  (CIK {cik})" if ticker else f"{name}  (CIK {cik})"
    return {"_index": "edgar_file", "_id": f"{adsh}:d{random.randint(10000, 99999)}s1.htm", "_score": 9.1,
            "_source": {"ciks": [cik], "display_names": [disp], "form": form, "root_forms": [form.split("/")[0]],
                        "file_date": filed, "adsh": adsh, "sics": [sic], "biz_states": [state]}}


def rss(items, title):
    body = "".join(
        f"<item><title>{t}</title><link>https://news.example.com/{i}</link>"
        f"<pubDate>{(datetime(2026, 11, 19, 13, tzinfo=timezone.utc) - timedelta(hours=h)).strftime('%a, %d %b %Y %H:%M:%S +0000')}</pubDate>"
        f"<description>{s}</description>{f'<source url=\"https://{src.lower()}.example.com\">{src}</source>' if src else ''}</item>"
        for i, (t, s, h, src) in enumerate(items))
    return f'<?xml version="1.0"?><rss version="2.0"><channel><title>{title}</title>{body}</channel></rss>'


def atom(items, title):
    body = "".join(
        f'<entry><title>{t}</title><link href="https://payments.example.com/{i}"/>'
        f"<updated>{(datetime(2026, 11, 19, 12, tzinfo=timezone.utc) - timedelta(hours=h)).isoformat()}</updated>"
        f"<summary>{s}</summary></entry>" for i, (t, s, h) in enumerate(items))
    return f'<?xml version="1.0"?><feed xmlns="http://www.w3.org/2005/Atom"><title>{title}</title>{body}</feed>'


def slug(url: str) -> str:
    return re.sub(r"[^a-z0-9]+", "-", url.lower()).strip("-")[-60:]


def main() -> None:
    real = yaml.safe_load((HERE.parents[1] / "config.yaml").read_text())
    config = {
        "edgar": {"forms": ["S-1", "F-1"], "lookback_days": 30, "keywords": ["fintech", "payments platform"],
                  "exclude_sics": ["6770"], "max_results": 25},
        "watchlist": TICKERS,
        "news": {"lookback_days": 3, "max_items": 25, "feeds": FEEDS},
        "trends": real["trends"],
        "summary": real["summary"],
    }
    (HERE / "config.yaml").write_text("# Fictional config for tests and --demo. Generated by make_fixtures.py\n"
                                      + yaml.safe_dump(config, sort_keys=False, allow_unicode=True))

    edgar = {"hits": {"total": {"value": 4}, "hits": [
        hit("Vaultline Financial, Inc.", "", "0002011001", "S-1", "2026-11-17", "6199", "CA"),
        hit("Closebook Technologies Corp", "", "0002011002", "S-1", "2026-11-12", "7372", "NY"),
        hit("Remitora Global Ltd", "", "0002011003", "F-1", "2026-11-06", "7374", "L2"),
        hit("Fintech Acquisition Corp IX", "FTAC", "0002011004", "S-1", "2026-11-14", "6770", "DE"),  # SPAC: excluded
    ]}}
    (HERE / "edgar.json").write_text(json.dumps(edgar, indent=1))

    (HERE / "yahoo").mkdir(exist_ok=True)
    for f in (HERE / "yahoo").glob("*.json"):
        f.unlink()
    for group in [TICKERS["benchmarks"], *TICKERS["groups"].values()]:
        for t in group:
            if t in START_PRICE and t != "NOVA":  # NOVA has no Yahoo data -> exercises the Stooq fallback
                (HERE / "yahoo" / f"{t}.json").write_text(json.dumps(yahoo(t)))
    # GHST has no data anywhere -> reported as missing
    (HERE / "stooq").mkdir(exist_ok=True)
    for f in (HERE / "stooq").glob("*.csv"):
        f.unlink()
    nova = series("NOVA")
    rows = ["Date,Open,High,Low,Close,Volume"] + [
        f"{(DEMO_DAY - timedelta(days=(len(nova) - i) * 1.45)).isoformat()},{c},{c},{c},{c},100000"
        for i, c in enumerate(nova)]
    (HERE / "stooq" / "nova.us.csv").write_text("\n".join(rows) + "\n")

    (HERE / "feeds").mkdir(exist_ok=True)
    for f in (HERE / "feeds").glob("*.xml"):
        f.unlink()
    (HERE / "feeds" / f"{slug(FEEDS['CFO Wire'])}.xml").write_text(rss([
        ("Closewise launches agentic AI assistant for month-end close", "The tool drafts reconciliations and flags anomalies.", 2, ""),
        ("Survey: 6 in 10 CFOs plan to add AI agents to FP&amp;A next year", "Finance leaders cite forecasting and close automation.", 5, ""),
        ("Ledgerline acquires spend-management startup Tallyo", "The deal expands its accounts payable suite.", 9, ""),
        ("Regulators weigh new rules for AI in credit decisions", "Compliance teams brace for guidance.", 20, ""),
        ("Old story that should be filtered out by the lookback window", "Stale.", 24 * 6, ""),
    ], "CFO Wire"))
    (HERE / "feeds" / f"{slug(FEEDS['Payments Weekly'])}.xml").write_text(atom([
        ("Orbit Pay shares slide after stablecoin settlement delay", "The company pushed back its USDC rollout.", 3),
        ("Banks pilot instant payments for B2B invoices", "Real-time payments volume keeps climbing.", 7),
        ("Tapp raises $120M Series C to expand embedded finance APIs", "The round values Tapp at $1.4B.", 11),
        ("Stablecoin issuers race to court enterprise treasurers", "Corporate treasury interest grows.", 15),
    ], "Payments Weekly"))
    (HERE / "feeds" / f"{slug(FEEDS['News search: fintech'])}.xml").write_text(rss([
        ("Vaultline Financial files for IPO as fintech listings rebound - Daily Ledger",
         "The lender filed an S-1 with the SEC.", 4, "Daily Ledger"),
        ("Agentic AI comes to accounts payable - Finance Today", "Vendors pitch autonomous invoice processing.", 6, "Finance Today"),
        ("Tapp raises $120M Series C to expand embedded finance APIs - Startup Beat",
         "Duplicate of a story from another feed.", 12, "Startup Beat"),
        ("Fraud losses from payment scams rose again this quarter - Risk Desk", "AML teams respond.", 18, "Risk Desk"),
    ], "News search"))
    # Broken Feed intentionally has no fixture.

    # Four weeks of quiet history so today's spikes register as "heating up".
    history = {}
    for i in range(1, 21):
        day = (DEMO_DAY - timedelta(days=i)).isoformat()
        history[day] = {t: random.choice([0, 0, 1]) for t in real["trends"]}
        history[day]["Regulation"] = random.choice([2, 3, 3, 4])
    (HERE / "trend_history.json").write_text(json.dumps(history, indent=1, sort_keys=True))
    print("fixtures written to", HERE)


if __name__ == "__main__":
    main()
